<?php
require_once __DIR__.'/../includes/init.php';require_role('petugas');require_once __DIR__.'/../includes/layout.php';$pdo=db();$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$page=page_number();$lim=12;$uid=current_user()['id'];$w=['(t.id_user=? OR t.id_user_keluar=?)'];$p=[$uid,$uid];if($q!==''){$w[]='(k.plat_nomor LIKE ? OR k.pemilik LIKE ? OR CAST(t.id_parkir AS CHAR) LIKE ?)';array_push($p,'%'.$q.'%','%'.$q.'%','%'.$q.'%');}if(in_array($status,['masuk','keluar'],true)){$w[]='t.status=?';$p[]=$status;}$error='';if($from!==''&&$to!==''){try{[$a,$b]=valid_date_range($from,$to);$w[]='t.waktu_masuk BETWEEN ? AND ?';array_push($p,$a,$b);}catch(Throwable $e){$error=$e->getMessage();}}elseif($from!==''||$to!=='')$error='Isi tanggal mulai dan akhir.';$ws=$w?' WHERE '.implode(' AND ',$w):'';$c=$pdo->prepare('SELECT COUNT(*) FROM tb_transaksi t JOIN tb_kendaraan k ON k.id_kendaraan=t.id_kendaraan'.$ws);$c->execute($p);$total=(int)$c->fetchColumn();$s=$pdo->prepare('SELECT t.id_parkir,t.waktu_masuk,t.waktu_keluar,t.status,t.durasi_jam,t.biaya_total,t.tarif_saat_masuk,k.plat_nomor,k.jenis_kendaraan,a.nama_area FROM tb_transaksi t JOIN tb_kendaraan k ON k.id_kendaraan=t.id_kendaraan JOIN tb_area_parkir a ON a.id_area=t.id_area'.$ws.' ORDER BY t.id_parkir DESC LIMIT '.$lim.' OFFSET '.(($page-1)*$lim));$s->execute($p);$rows=$s->fetchAll();render_header('Riwayat Transaksi','riwayat');?>
<div class="page-intro"><div><h2>Riwayat transaksi</h2><p>Cari transaksi yang melibatkan Anda sebagai petugas masuk atau keluar; data petugas lain tidak ditampilkan.</p></div></div><?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><section class="panel"><form method="get" class="filter-row"><div class="field" style="min-width:210px"><label>Pencarian</label><input name="q" value="<?= h($q) ?>" placeholder="Plat / pemilik / nomor transaksi"></div><div class="field"><label>Status</label><select name="status"><option value="">Semua</option><option value="masuk" <?= $status==='masuk'?'selected':'' ?>>Masuk</option><option value="keluar" <?= $status==='keluar'?'selected':'' ?>>Keluar</option></select></div><div class="field"><label>Dari tanggal masuk</label><input type="date" name="from" value="<?= h($from) ?>"></div><div class="field"><label>Sampai tanggal</label><input type="date" name="to" value="<?= h($to) ?>"></div><button class="btn btn-primary">Cari transaksi</button><a class="btn btn-secondary" href="<?= h(url('petugas/riwayat.php')) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>ID</th><th>Plat nomor</th><th>Area</th><th>Masuk</th><th>Keluar</th><th>Status</th><th>Durasi</th><th>Biaya</th><th>Struk</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td class="td-main">#<?= (int)$r['id_parkir'] ?></td><td class="td-main"><?= h($r['plat_nomor']) ?><div class="muted"><?= h(ucfirst($r['jenis_kendaraan'])) ?></div></td><td><?= h($r['nama_area']) ?></td><td><?= h(tanggal($r['waktu_masuk'])) ?></td><td><?= h(tanggal($r['waktu_keluar'])) ?></td><td><?= status_badge($r['status']) ?></td><td><?= $r['durasi_jam']===null?'-':(int)$r['durasi_jam'].' jam' ?></td><td><?= $r['biaya_total']===null?'-':h(rupiah($r['biaya_total'])) ?></td><td><?php if($r['status']==='keluar'): ?><a class="btn btn-secondary btn-sm" href="<?= h(url('petugas/struk.php?id='.(int)$r['id_parkir'])) ?>">Lihat / cetak</a><?php else: ?><a class="btn btn-primary btn-sm" href="<?= h(url('petugas/transaksi-keluar.php?id='.(int)$r['id_parkir'])) ?>">Proses keluar</a><?php endif; ?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="9"><div class="empty-state">Tidak ada transaksi yang cocok dengan filter.</div></td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span><?= $total ?> transaksi ditemukan</span><?= pagination($total,$lim,$page,url('petugas/riwayat.php?q='.rawurlencode($q).'&status='.rawurlencode($status).'&from='.rawurlencode($from).'&to='.rawurlencode($to))) ?></div></section><?php render_footer(); ?>